import math

def cross_entropy(p, q):
    return -sum(pi * math.log(qi) for pi, qi in zip(p, q) if pi > 0)

def entropy(p):
    return cross_entropy(p, p)

def kl(p, q):
    return sum(pi * math.log(pi / qi) for pi, qi in zip(p, q) if pi > 0)

import numpy as np

def lm_loss(probs, targets):
    T = probs.shape[0]
    p_correct = probs[np.arange(T), targets]
    loss = -np.log(p_correct).mean()
    return loss, np.exp(loss)
